using UnityEngine;

/// <summary>
/// Table of every prefab that Network.Instantiate may spawn. Legacy Unity networking identified prefabs by asset id;
/// we send the index into this table instead. Generated by Assets/Editor/ZbNetPrefabsBuilder.cs before each build
/// (same build on all peers => same table).
/// </summary>
public class ZbNetPrefabs : ScriptableObject
{
    public GameObject[] prefabs = new GameObject[0];
}
